import { useEffect, useState } from "react";
import { Link } from "react-router-dom";

function History() {

  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);

  //////////////////////////////////////////////////////////////
  // Fetch Order History
  //////////////////////////////////////////////////////////////

  useEffect(() => {
    async function fetchHistory() {
      try {
        const res = await fetch("http://localhost:5000/order-history", {
          credentials: "include"
        });

        if (!res.ok) {
          setOrders([]);
          setLoading(false);
          return;
        }

        const data = await res.json();
        setOrders(Array.isArray(data) ? data : []);
        setLoading(false);

      } catch (error) {
        setOrders([]);
        setLoading(false);
      }
    }

    fetchHistory();
  }, []);

  //////////////////////////////////////////////////////////////
  // REMOVE ITEM FROM DATABASE + UI
  //////////////////////////////////////////////////////////////

  const removeItem = async (orderId, productId) => {
    try {
      const res = await fetch(
        "http://localhost:5000/remove-history-item",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json"
          },
          credentials: "include",
          body: JSON.stringify({
            orderId,
            productId
          })
        }
      );

      if (!res.ok) {
        alert("Failed to remove item ❌");
        return;
      }

      // Update UI after backend delete
      setOrders(prev =>
        prev.map(order =>
          order._id === orderId
            ? {
                ...order,
                items: order.items.filter(
                  item => item.productId !== productId
                )
              }
            : order
        )
      );

    } catch (error) {
      alert("Server error ❌");
    }
  };

  //////////////////////////////////////////////////////////////
  // Loading
  //////////////////////////////////////////////////////////////

  if (loading) {
    return (
      <div style={outerStyle}>
        <h2 style={{ textAlign: "center" }}>Loading...</h2>
      </div>
    );
  }

  //////////////////////////////////////////////////////////////
  // UI
  //////////////////////////////////////////////////////////////

  return (
    <div style={outerStyle}>

      <h1 style={headingStyle}>Purchased Items</h1>

      {orders.length === 0 ? (
        <h2 style={{ textAlign: "center" }}>
          No Purchased Items Yet
        </h2>
      ) : (

        orders.map((order) => (

          <div key={order._id}>

            {Array.isArray(order.items) &&
              order.items.map((item) => (

                <div
  key={item.productId}
  className="history-card"
  style={cartBoxStyle}
>


                  {/* Image */}
                  <div 
                    className="history-image"
                    style={imageBoxStyle}>
                    <img
                      src={item.image}
                      alt={item.title}
                      style={imageStyle}
                    />
                  </div>

                  {/* Details */}
                  <div style={{ flex: 1 }}>
                    <h2>{item.title}</h2>
                    <h3 style={{ color: "green" }}>${item.price}</h3>
                    <p style={{ fontSize: "18px" }}>
                      Quantity: {item.quantity}
                    </p>
                  </div>

                  {/* Remove Button */}
                  <button
                    className="history-remove"
                    onClick={() =>
                      removeItem(order._id, item.productId)
                    }
                    style={removeBtnStyle}
                  >
                    Remove
                  </button>

                </div>

              ))}

          </div>

        ))

      )}

      <div style={{ textAlign: "center", marginTop: "40px" }}>
        <Link to="/" style={backBtnStyle}>
          Continue Shopping
        </Link>
      </div>

    </div>
  );
}

//////////////////////////////////////////////////////////////
// Styles
//////////////////////////////////////////////////////////////

const outerStyle = {
  minHeight: "100vh",
  padding: "40px",
  backgroundColor: "#b7cdd6"
};

const headingStyle = {
  textAlign: "center",
  marginBottom: "40px"
};

const cartBoxStyle = {
  display: "flex",
  alignItems: "center",
  backgroundColor: "white",
  padding: "20px",
  marginBottom: "20px",
  borderRadius: "15px",
  boxShadow: "0 5px 15px rgba(0,0,0,0.1)"
};

const imageBoxStyle = {
  width: "250px",
  height: "200px",
  marginRight: "30px",
  borderRadius: "10px",
  overflow: "hidden"
};

const imageStyle = {
  width: "100%",
  height: "100%",
  objectFit: "cover"
};

const removeBtnStyle = {
  padding: "10px 15px",
  backgroundColor: "red",
  color: "white",
  border: "none",
  borderRadius: "8px",
  cursor: "pointer",
  height: "40px"
};

const backBtnStyle = {
  padding: "10px 20px",
  backgroundColor: "blue",
  color: "white",
  textDecoration: "none",
  borderRadius: "8px"
};
<style>
{`
  @media (max-width: 768px) {

    .history-card {
      flex-direction: column !important;
      align-items: center !important;
      text-align: center;
    }

    .history-image {
      width: 100% !important;
      height: 220px !important;
      margin-right: 0 !important;
      margin-bottom: 15px;
    }

    .history-remove {
      width: 100%;
      margin-top: 15px;
    }

  }
`}
</style>


export default History;
